def _make_train_function(self):
    if not hasattr(self, 'train_function'):
        raise RuntimeError('You must compile your model before using it.')
    self._check_trainable_weights_consistency()
    if self.train_function is None:
        inputs = self._feed_inputs + self._feed_targets + self._feed_sample_weights
        if self._uses_dynamic_learning_phase():
            inputs += [K.learning_phase()]
        with K.name_scope('training'):
            with K.name_scope(self.optimizer.__class__.__name__):
                training_updates = self.optimizer.get_updates(params=self._collected_trainable_weights, loss=self.total_loss)
            updates = self.updates + training_updates + self.metrics_updates
            self.train_function = K.function(inputs, [self.total_loss] + self.metrics_tensors, updates=updates, name='train_function', **self._function_kwargs)

def _make_test_function(self):
    if not hasattr(self, 'test_function'):
        raise RuntimeError('You must compile your model before using it.')
    if self.test_function is None:
        inputs = self._feed_inputs + self._feed_targets + self._feed_sample_weights
        if self._uses_dynamic_learning_phase():
            inputs += [K.learning_phase()]
        self.test_function = K.function(inputs, [self.total_loss] + self.metrics_tensors, updates=self.state_updates + self.metrics_updates, name='test_function', **self._function_kwargs)

def _make_predict_function(self):
    if not hasattr(self, 'predict_function'):
        self.predict_function = None
    if self.predict_function is None:
        if self._uses_dynamic_learning_phase():
            inputs = self._feed_inputs + [K.learning_phase()]
        else:
            inputs = self._feed_inputs
        kwargs = getattr(self, '_function_kwargs', {})
        self.predict_function = K.function(inputs, self.outputs, updates=self.state_updates, name='predict_function', **kwargs)

def _standardize_user_data(self, x, y=None, sample_weight=None, class_weight=None, check_array_lengths=True, batch_size=None):
    all_inputs = []
    if not self.built:
        if isinstance(x, (list, tuple)):
            if not all((isinstance(v, np.ndarray) or K.is_tensor(v) for v in x)):
                raise ValueError('Please provide as model inputs either a single array or a list of arrays. You passed: x=' + str(x))
            all_inputs += list(x)
        elif isinstance(x, dict):
            raise ValueError('Please do not pass a dictionary as model inputs.')
        else:
            if not isinstance(x, np.ndarray) and (not K.is_tensor(x)):
                raise ValueError('Please provide as model inputs either a single array or a list of arrays. You passed: x=' + str(x))
            all_inputs.append(x)
        if not self.inputs:
            self._set_inputs(x)
    if y is not None:
        if not self.optimizer:
            raise RuntimeError('You must compile a model before training/testing. Use `model.compile(optimizer, loss)`.')
        if not self._is_compiled:
            if isinstance(y, (list, tuple)):
                if not all((isinstance(v, np.ndarray) or K.is_tensor(v) for v in y)):
                    raise ValueError('Please provide as model targets either a single array or a list of arrays. You passed: y=' + str(y))
            elif isinstance(y, dict):
                raise ValueError('Please do not pass a dictionary as model targets.')
            elif not isinstance(y, np.ndarray) and (not K.is_tensor(y)):
                raise ValueError('Please provide as model targets either a single array or a list of arrays. You passed: y=' + str(y))
            if y is not None:
                all_inputs += to_list(y, allow_tuple=True)
            if any((K.is_tensor(v) for v in all_inputs)):
                if not all((K.is_tensor(v) for v in all_inputs)):
                    raise ValueError('Do not pass inputs that mix Numpy arrays and symbolic tensors. You passed: x=' + str(x) + '; y=' + str(y))
            y = to_list(y, allow_tuple=True)
            target_tensors = [v for v in y if K.is_tensor(v)]
            if not target_tensors:
                target_tensors = None
            self.compile(optimizer=self.optimizer, loss=self.loss, metrics=self.metrics, loss_weights=self.loss_weights, target_tensors=target_tensors)
    if any((K.is_tensor(v) for v in all_inputs)):
        return ([], [], [])
    if not self._is_graph_network:
        feed_input_names = self._feed_input_names
        feed_input_shapes = None
    else:
        feed_input_names = self._feed_input_names
        feed_input_shapes = self._feed_input_shapes
    x = standardize_input_data(x, feed_input_names, feed_input_shapes, check_batch_axis=False, exception_prefix='input')
    if y is not None:
        if not self._is_graph_network:
            feed_output_names = self._feed_output_names
            feed_output_shapes = None
            feed_sample_weight_modes = [None for _ in self.outputs]
        else:
            feed_output_names = self._feed_output_names
            feed_sample_weight_modes = self._feed_sample_weight_modes
            feed_output_shapes = []
            for output_shape, loss_fn in zip(self._feed_output_shapes, self._feed_loss_fns):
                if loss_fn is losses.sparse_categorical_crossentropy:
                    if K.image_data_format() == 'channels_first' and len(output_shape) in [4, 5]:
                        feed_output_shapes.append((output_shape[0], 1) + output_shape[2:])
                    else:
                        feed_output_shapes.append(output_shape[:-1] + (1,))
                elif not hasattr(loss_fn, '__name__') or getattr(losses, loss_fn.__name__, None) is None:
                    feed_output_shapes.append(None)
                else:
                    feed_output_shapes.append(output_shape)
        y = standardize_input_data(y, feed_output_names, feed_output_shapes, check_batch_axis=False, exception_prefix='target')
        sample_weights = standardize_sample_weights(sample_weight, feed_output_names)
        class_weights = standardize_class_weights(class_weight, feed_output_names)
        sample_weights = [standardize_weights(ref, sw, cw, mode) for ref, sw, cw, mode in zip(y, sample_weights, class_weights, feed_sample_weight_modes)]
        if check_array_lengths:
            check_array_length_consistency(x, y, sample_weights)
        if self._is_graph_network:
            check_loss_and_target_compatibility(y, self._feed_loss_fns, feed_output_shapes)
    else:
        y = []
        sample_weights = []
    if self.stateful and batch_size:
        if x[0].shape[0] % batch_size != 0:
            raise ValueError('In a stateful network, you should only pass inputs with a number of samples that can be divided by the batch size. Found: ' + str(x[0].shape[0]) + ' samples')
    return (x, y, sample_weights)

def _get_callback_model(self):
    """Returns the Callback Model for this Model."""
    if hasattr(self, 'callback_model') and self.callback_model:
        return self.callback_model
    return self
